vars['cp_fail'] = '0'
vars['promise_state'] = 'none'
vars['deal_state'] = 'none'
vars['farewell'] = 'Thank you for your time. Goodbye.'
'''

CHECK_CB_CODE = HELP + '''
try:
    now = parse_now(vars.get('now'))
    today = now.date()
    nb = add_bd(today, 1)
    d = resolve_day(vars.get('cb_day_text'), today)
    t = str(vars.get('cb_time') or '')
    mt = re.match(r'^(\\d{1,2}):(\\d{2})$', t)
    attempts = int(str(vars.get('cb_attempts') or '0'))
    if d is None or mt is None:
        vars['cb_state'] = 'retry'
        vars['cb_feedback'] = 'The day or time could not be understood. Ask for an exact day and an exact time.'
    else:
        hh = int(mt.group(1))
        mm = int(mt.group(2))
        mins = hh * 60 + mm
        cand = datetime.datetime(d.year, d.month, d.day, min(hh, 23), mm)
        ok = (d == today or d == nb) and 600 <= mins <= 1140 and cand > now
        if ok:
            vars['cb_state'] = 'valid'
            vars['cb_date_iso'] = d.isoformat()
            vars['cb_time_norm'] = '%02d:%02d' % (hh, mm)
            vars['cb_date_spoken'] = sp(d)
        else:
            attempts = attempts + 1
            vars['cb_attempts'] = str(attempts)
            if attempts >= 2:
                vars['cb_state'] = 'fail'
            else:
                vars['cb_state'] = 'retry'
                vars['cb_feedback'] = 'The time the person offered is NOT possible. Say briefly that a callback is only possible today or the next business day between 10:00 and 19:00 and later than now, and ask ONCE for another time. Do not ask a third time.'
except Exception:
    vars['cb_state'] = 'retry'
    vars['cb_feedback'] = 'Ask for an exact day and time.'
vars['cb_day_text'] = 'none'
vars['cb_time'] = 'none'
'''

PREPARE_CODE = HELP + '''
def getp():
    prods = vars.get('products')
    if isinstance(prods, str):
