}

nodes["get_account"] = api_node(
    "get_account",
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 2}, "function": {
        "name": "get_account", "handler": "__function__:api_call", "description": "Get the late products.",
        "parameters": {"type": "object", "properties": {
            "url": {"type": "string", "default": BASE + "get_account"},
            "method": {"type": "string", "default": "POST"}, "headers": HDR,
            "body": {"type": "object", "required": [], "properties": {
                "customer_id": {"type": "string", "default": "{{customer_id}}"}}}}}},
    },
    [{"path": "data.products", "variable": "products"}],
    [tr("set_service_error", "lookup failed", {"logic": "or", "conditions": [
        {"variable": "get_account_failure_count", "operator": "greater_than", "operand": 0}]}),
     tr("prepare_deal", "always")],
    "prepare_deal")

nodes["prepare_deal"] = code_node("prepare_deal", PREPARE_CODE, [
    tr("negotiate", "ready", eq("deal_state", "ready")),
    tr("set_service_error", "no product data"),
], "negotiate")

nodes["negotiate"] = {
    "name": "negotiate", "node_type": "conversation",
    "on_enter": {"type": "tts", "text": "{{deal_intro}}"},
    "on_enter_first_entry_only": True,
    "task_message": NEGOTIATE_TASK,
    "tools": [api_fn(
        "create_promise", "create_promise",
        {"product_id": {"type": "string", "default": "{{product_id}}", "description": "product_id of the late product."},
         "amount": {"type": "number", "default": "{{amount}}", "description": "The amount the customer confirmed, as a number."},
         "date": {"type": "string", "default": "{{date}}", "description": "The confirmed promise date as YYYY-MM-DD."}},
        ["product_id", "amount", "date"],
        desc="Record the payment promise. CALL it only after the customer clearly said yes to your read-back of product, amount and date. Never say the promise is recorded without calling it.",
        post=PROMISE_POST)],
    "max_node_turns": 40, "max_turn_transition": "set_refused",
    "transitions": [
        tr("set_promise", "The promise was recorded", {"logic": "or", "conditions": [
            {"variable": "promise_state", "operator": "equals", "operand": "recorded"},
            {"variable": "create_promise_response.data.ok", "operator": "equals", "operand": "true"},
            {"variable": "create_promise_response.data.ok", "operator": "equals", "operand": "True"}]}),
        tr("set_service_error", "create_promise failed twice", {"logic": "or", "conditions": [
            {"variable": "cp_fail", "operator": "greater_than", "operand": 1}]}),
        tool_t("set_refused", "All allowed persuasion attempts are used up and the customer still refuses, or the customer says twice that they do not want to talk"),
        tool_t("set_paid", "The customer says they already paid this past-due amount"),
        tool_t("set_dispute", "The customer says the debt is not theirs, they never had the product, or it was closed or paid off in the past"),
        tool_t("transfer_support", "The customer mentioned illness, a death in the family or job loss and ACCEPTED to be connected to customer support"),
        tool_t("set_hardship", "The customer mentioned illness, a death in the family or job loss, DECLINED customer support and named no date or amount"),
        tool_t("transfer_restructuring", "The customer asks for a new payment plan or lower instalments"),
        tool_t("transfer_human", "The customer insists on speaking to a human after being asked once whether you can help"),
    ],
}

def transfer_node(name, queue, setnode):
    return api_node(
        name,
        {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {
            "name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Transfer.",
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + "transfer_to_agent"},
                "method": {"type": "string", "default": "POST"}, "headers": HDR,
                "body": {"type": "object", "required": [], "properties": {
                    "customer_id": {"type": "string", "default": "{{customer_id}}"},
                    "queue": {"type": "string", "default": queue}}}}}}},
        [], [tr(setnode, "always")], setnode)


nodes["transfer_support"] = transfer_node("transfer_support", "support", "set_transferred_support")
nodes["transfer_restructuring"] = transfer_node("transfer_restructuring", "restructuring", "set_transferred_restructuring")
nodes["transfer_human"] = transfer_node("transfer_human", "general", "set_transferred_human")

SETS = {
    "set_promise": ("promise", "none", "Your payment promise is recorded. You will receive a text message confirming this promise. Thank you for your time. Goodbye."),
    "set_paid": ("paid", "none", "Thank you for letting us know. Payments can take one business day to appear. Goodbye."),
    "set_transferred_support": ("transferred", "support", "I am connecting you to the customer support team now. Thank you, goodbye."),
    "set_transferred_restructuring": ("transferred", "restructuring", "I am connecting you to the right team now. Thank you, goodbye."),
    "set_transferred_human": ("transferred", "human", "I am connecting you to a colleague now. Thank you, goodbye."),
    "set_refused": ("no_promise", "refused", "I understand. Thank you for your time. Goodbye."),
    "set_hardship": ("no_promise", "hardship", "I understand. Thank you for your time. Goodbye."),
    "set_dispute": ("no_promise", "dispute", "I understand, and I will not take any payment promise on this call. Thank you for your time. Goodbye."),
    "set_service_error": ("no_promise", "service_error", "I am sorry, I could not complete this because of a system problem, and nothing has been recorded. Thank you for your time. Goodbye."),
    "set_not_verified_failed": ("not_verified", "failed", "I am sorry, I could not verify your identity. Please use the Freya Bank mobile app or visit a branch. Thank you, goodbye."),
    "set_not_verified_declined": ("not_verified", "declined", "I understand. Thank you for your time. Goodbye."),
    "set_nr_no_callback": ("not_reached", "no_callback", "Thank you for your time. Goodbye."),
    "set_nr_wrong_number": ("not_reached", "wrong_number", "I am sorry for the trouble. Thank you, goodbye."),
    "set_nr_deceased": ("not_reached", "deceased", "I am sorry for your loss. Goodbye."),
    "set_nr_unclear": ("not_reached", "unclear", "I am sorry, I could not hear you well. Thank you, goodbye."),
}
for k, (o, r, f) in SETS.items():
    nodes[k] = code_node(k, set_code(o, r, f), [tr("final_end", "always")], "final_end")

nodes["set_nr_callback"] = code_node("set_nr_callback", set_code(
    "not_reached", "callback", dynamic="vars['farewell'] = 'Thank you. We will call back ' + str(vars.get('cb_date_spoken')) + ' at ' + str(vars.get('cb_time_norm')) + '. Goodbye.'\n"),
    [tr("final_end", "always")], "final_end")

nodes["final_end"] = {
