    "- 'I already paid': say payments can take one business day to appear, take no promise, call transition_to_set_paid.\n"
    "- 'This debt is not mine', 'I never had this product', or the product was closed or paid off in the past: do not argue, take no promise, call transition_to_set_dispute.\n"
    "- A request for a new payment plan or lower instalments: do not describe any plan; call transition_to_transfer_restructuring.\n"
    "- A request for a human: ask once whether you can help first; if they insist, call transition_to_transfer_human.\n"
    "- If the customer says twice that they do not want to talk, call transition_to_set_refused.\n"
    "- A relative or another person is not allowed here; only the verified customer is on the call."
)

VERIFY_POST = '''
try:
    if isinstance(result, dict):
        result.pop('header', None)
    d = result.get('data') if isinstance(result, dict) else None
    if isinstance(d, dict):
        hint = d.get('hint')
        okv = str(d.get('ok')).lower()
        if hint == 'day_month_swapped':
            msg = 'The day and month look swapped. Ask the customer to say the month as a word (for example 4 May 1980). This does NOT count as a wrong answer. Then call verify_identity again with the date_of_birth.'
        elif okv == 'false':
            msg = 'The value was not accepted and it was not counted as a wrong answer. Ask the customer to say it again (for a date of birth: day, month as a word, year), then call verify_identity again.'
        elif str(d.get('all_verified')).lower() == 'true':
            msg = 'Both answers are verified. Say a brief thank you only.'
        elif str(d.get('verified')).lower() == 'true':
            msg = 'This answer is correct. Now ask the NEXT security question (the last four digits of the phone number on file) if it was not asked yet. Do not state anything about the account.'
        else:
            left = d.get('wrong_answers_left')
            if left is not None and int(left) <= 0:
                msg = 'The check has ended. Do not state anything about the account.'
            else:
                msg = 'That answer did not match. Say so briefly (do not reveal the right answer) and ask the same question again. Wrong answers left: ' + str(left) + '.'
        d['what_to_do_next'] = msg
except Exception:
    pass
'''

VERIFY_PRE = '''
try:
    b = config.get('body')
    if isinstance(b, dict):
        a = str(b.get('answer') or '').strip()
        f = str(b.get('field') or '')
        if f == 'phone_last4':
            digits = re.sub(r'\\D', '', a)
            if len(digits) >= 4:
                b['answer'] = digits[-4:]
        elif f == 'date_of_birth':
            m = re.match(r'^(\\d{1,2})[/.\\-](\\d{1,2})[/.\\-](\\d{4})$', a)
            if m:
                b['answer'] = '%s-%02d-%02d' % (m.group(3), int(m.group(2)), int(m.group(1)))
except Exception:
    pass
'''
VERIFY_PRE = "import re\n" + VERIFY_PRE

PROMISE_POST = '''
try:
    if isinstance(result, dict):
        result.pop('header', None)
    d = result.get('data') if isinstance(result, dict) else None
    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'
    if ok:
        vars['promise_state'] = 'recorded'
        msg = 'The promise is recorded. Say nothing more than a brief thanks.'
    else:
        n = int(str(vars.get('cp_fail') or '0')) + 1
        vars['cp_fail'] = str(n)
        if n >= 2:
            msg = 'It failed a second time. Say only that you could not complete it because of a technical problem.'
        else:
            msg = 'The call failed with a technical problem. Tell the customer there was a technical problem and you will try once more (do not use the words recorded, saved or confirmed in that sentence). Then call create_promise again at once with exactly the same values, without asking for confirmation again.'
    if isinstance(d, dict):
        d['what_to_do_next'] = msg
    elif isinstance(result, dict):
        result['what_to_do_next'] = msg
except Exception:
    pass
'''

