def transfer_node(name, queue, setnode):
    return api_node(
        name,
        {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {
            "name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Transfer.",
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + "transfer_to_agent"},
                "method": {"type": "string", "default": "POST"}, "headers": HDR,
                "body": {"type": "object", "required": [], "properties": {
                    "customer_id": {"type": "string", "default": "{{customer_id}}"},
                    "queue": {"type": "string", "default": queue}}}}}}},
        [], [tr(setnode, "always")], setnode)


